2	
3	export type GiftStatus = 'purchased' | 'redeemed' | 'consumed' | 'expired' | 'refunded';
4	export type GiftCadence = 'month' | 'year';
5	export type RedeemableCheckFailureReason = 'redeemed' | 'consumed' | 'expired' | 'refunded';
6	export type RedeemableCheckResult =
7	    | {redeemable: true}
8	    | {redeemable: false; reason: RedeemableCheckFailureReason};
9	
10	interface GiftData {
11	    token: string;
12	    buyerEmail: string;
13	    buyerMemberId: string | null;
14	    redeemerMemberId: string | null;
15	    tierId: string;
16	    cadence: GiftCadence;
17	    duration: number;
18	    currency: string;
19	    amount: number;
20	    stripeCheckoutSessionId: string;
21	    stripePaymentIntentId: string;
22	    consumesAt: Date | null;
23	    expiresAt: Date;
24	    status: GiftStatus;
25	    purchasedAt: Date;
26	    redeemedAt: Date | null;
27	    consumedAt: Date | null;
28	    expiredAt: Date | null;
29	    refundedAt: Date | null;
30	}
31	
32	export interface GiftFromPurchaseData {
33	    token: string;
34	    buyerEmail: string;
35	    buyerMemberId: string | null;
36	    tierId: string;
37	    cadence: GiftCadence;
38	    duration: number;
39	    currency: string;
40	    amount: number;
41	    stripeCheckoutSessionId: string;
42	    stripePaymentIntentId: string;
43	}
44	
45	export class Gift {
46	    token: string;
47	    buyerEmail: string;
48	    buyerMemberId: string | null;
49	    redeemerMemberId: string | null;
50	    tierId: string;
51	    cadence: GiftCadence;
52	    duration: number;
53	    currency: string;
54	    amount: number;
55	    stripeCheckoutSessionId: string;
56	    stripePaymentIntentId: string;
57	    consumesAt: Date | null;
58	    expiresAt: Date;
59	    status: GiftStatus;
60	    purchasedAt: Date;
61	    redeemedAt: Date | null;
62	    consumedAt: Date | null;
63	    expiredAt: Date | null;
64	    refundedAt: Date | null;
65	
66	    constructor(data: GiftData) {
67	        this.token = data.token;
68	        this.buyerEmail = data.buyerEmail;
69	        this.buyerMemberId = data.buyerMemberId;
70	        this.redeemerMemberId = data.redeemerMemberId;
71	        this.tierId = data.tierId;
72	        this.cadence = data.cadence;
73	        this.duration = data.duration;
74	        this.currency = data.currency;
75	        this.amount = data.amount;
76	        this.stripeCheckoutSessionId = data.stripeCheckoutSessionId;
77	        this.stripePaymentIntentId = data.stripePaymentIntentId;
78	        this.consumesAt = data.consumesAt;
79	        this.expiresAt = data.expiresAt;
80	        this.status = data.status;
81	        this.purchasedAt = data.purchasedAt;
82	        this.redeemedAt = data.redeemedAt;
83	        this.consumedAt = data.consumedAt;
84	        this.expiredAt = data.expiredAt;
85	        this.refundedAt = data.refundedAt;
86	    }
87	
88	    static fromPurchase(data: GiftFromPurchaseData) {
89	        const now = new Date();
90	        const expiresAt = new Date(now);
91	
92	        expiresAt.setDate(expiresAt.getDate() + GIFT_EXPIRY_DAYS);
93	
94	        return new Gift({
95	            ...data,
96	            redeemerMemberId: null,
97	            consumesAt: null,
98	            expiresAt,
99	            status: 'purchased',
100	            purchasedAt: now,
101	            redeemedAt: null,
102	            consumedAt: null,
103	            expiredAt: null,
104	            refundedAt: null
105	        });
106	    }
107	
108	    isRedeemed() {
109	        return this.redeemedAt !== null;
110	    }
111	
112	    isExpired() {
113	        return this.expiredAt !== null;
114	    }
115	
116	    isRefunded() {
117	        return this.refundedAt !== null;
118	    }
119	
120	    isConsumed() {
121	        return this.consumedAt !== null;
122	    }
123	
124	    checkRedeemable(): RedeemableCheckResult {
125	        if (this.isRedeemed()) {
126	            return {redeemable: false, reason: 'redeemed'};
127	        }
128	
129	        if (this.isConsumed()) {
130	            return {redeemable: false, reason: 'consumed'};
131	        }
132	
133	        if (this.isExpired()) {
134	            return {redeemable: false, reason: 'expired'};
135	        }
136	
137	        if (this.isRefunded()) {
138	            return {redeemable: false, reason: 'refunded'};
139	        }
140	
141	        return {redeemable: true};
142	    }
143	}
