                });
            }
            }
        }

        return gift;
    }

    async redeem({token, memberId}: {token: string; memberId: string}): Promise<Gift> {
        return this.giftRepository.transaction(async (trx) => {
            const gift = await this.giftRepository.getByToken(token, {transacting: trx, forUpdate: true});

            if (!gift) {
                throw new errors.NotFoundError({
                    message: tpl(messages.giftNotFound)
                });
            }

            const member = await this.memberRepository.get({id: memberId}, {transacting: trx, forUpdate: true});

            if (!member) {
                throw new errors.NotFoundError({
                    message: tpl(messages.memberNotFound, {memberId})
                });
            }

            await this.assertRedeemable(gift, member.get('status'));

            const redeemed = gift.redeem({memberId, redeemedAt: new Date()});

            await this.memberRepository.update({
                products: [{id: gift.tierId, expiry_at: redeemed.consumesAt}],
                status: 'gift'
            }, {id: memberId, transacting: trx});

            await this.giftRepository.save(redeemed, {transacting: trx});

            return redeemed;
        });
