const messages = {
    giftSubscriptionsNotEnabled: 'Gift subscriptions are not enabled on this site.',
    giftNotFound: 'This gift does not exist.'
};

/** @type {import('@tryghost/api-framework').Controller} */
module.exports = {
    docName: 'gifts',

    isRedeemable: {
        headers: {
            cacheInvalidate: false
        },
        data: [
            'token'
        ],
        validation: {
            data: {
                token: {
                    type: 'string',
                    required: true
                }
            }
        },
        permissions: false,
        async query(frame) {
            if (!labs.isSet('giftSubscriptions')) {
                throw new errors.BadRequestError({
                    message: tpl(messages.giftSubscriptionsNotEnabled)
                });
            }

            const currentMember = frame.options.context.member;
            const gift = await giftService.service.getRedeemable(
                frame.data.token,
                currentMember?.status ?? null
            );

            const tier = await tiersService.api.read(gift.tierId);

            if (!tier) {
                throw new errors.NotFoundError({
                    message: tpl(messages.giftNotFound)
                });
            }

            const tierJSON = tier.toJSON ? tier.toJSON() : tier;

            return {
                token: gift.token,
                cadence: gift.cadence,
                duration: gift.duration,
                currency: gift.currency,
                amount: gift.amount,
                expires_at: gift.expiresAt,
                tier: {
                    id: tierJSON.id,
                    name: tierJSON.name,
                    description: tierJSON.description ?? null,
                    benefits: Array.isArray(tierJSON.benefits) ? tierJSON.benefits : []
                }
            };
        }
    }
};
